namespace gatelogic {

/// The roster and the queue this firmware actually builds, named once so the
/// orchestration and the composition root cannot be given different sizes.
using GateRoster = roster::Roster<kGateRosterEntries>;
using GateQueue = eventq::EventQueue<kGateEventSlots>;

class GateApp {
public:
  /// Everything the loop needs, by name rather than by position.
  ///
  /// A sixteen-argument constructor is unreadable, unreviewable and over the
  /// complexity gate's argument limit; sixteen positional aggregate
  /// initialisers are worse, because two pointers of the same type swapped is a
  /// build that compiles and a door that blinks when it should open. Assigned
  /// field by field in main.cpp instead, where each line says what it wires.
  struct Ports {
    hal::IClock* clock = nullptr;
    IScannerBytes* scanner = nullptr;
    IWatchdog* watchdog = nullptr;
    ILink* link = nullptr;

    GateApi* api = nullptr;
    devlink::ApiBreaker* breaker = nullptr;

    LockDriver* lock = nullptr;
    UnlockTimer* unlock = nullptr;
    LedPattern* led = nullptr;
    IPinOut* ledPin = nullptr;
    bool ledActiveHigh = true;

    ScanAssembler* assembler = nullptr;
    ScanDebounce* debounce = nullptr;
    GateRoster* roster = nullptr;
    GateQueue* queue = nullptr;

    /// WHAT THIS BOARD NOTICES ABOUT ITSELF, aggregated. Required, like every
    /// other port here except the decision log: a board whose fault counts are
    /// silently always zero is indistinguishable from a healthy one, which is
    /// the failure every counter in this firmware exists to end.
    ///
    /// It is the SAME instance `GateApi` and `FaultingStore` hold, because a
    /// second log would be a second set of windows and a board reporting each
    /// code twice at half the rate it thinks.
    FaultLog* faults = nullptr;

    /// OPTIONAL, and nullptr on every board. The native simulator's console —
    /// see IDecisionLog for why a refusal reason is otherwise unobservable
    /// outside this class.
    IDecisionLog* log = nullptr;

    /// 12 lowercase hex characters, filled by the composition root before
    /// begin(). Held by pointer: it is written once at boot and read for the
    /// life of the image.
    const char* mac = nullptr;
    const char* firmwareVersion = nullptr;

    /// THIS BOOT'S IDENTITY, and the third field of the server's idempotency
    /// key (round G4, C2). A per-boot random 32-bit value: `esp_random()` on
    /// the board, a flag or the clock in the simulator, a literal in a test.
    ///
    /// It is a PORT rather than something this class generates, for the reason
    /// everything else here is: a class that reached for a platform RNG could
    /// only ever be tested against itself, and a boot identity a test cannot
    /// pin is a deduplication rule no test can prove.
    ///
    /// Zero means "this board has no boot identity", which omits the field and
    /// gives the server exactly the (device, seq) behaviour it always had — so
    /// a composition root that forgets this is degraded rather than broken.
    /// The gate's does not forget; the assert in `begin()` is what says so.
    uint32_t bootId = 0U;

    /// CONSECUTIVE WATCHDOG RESETS BEFORE THIS BOOT (round G4, A4). Zero on a
    /// healthy boot, which is every boot on a healthy board.
    ///
    /// A port for the same reason `bootId` is: it comes from `esp_reset_reason()`
    /// and a counter in RTC no-init memory, both of which are platform facts,
    /// and a loop that reached for them could only be tested against itself.
    /// `BootRecovery.h` carries what it means and what it costs.
    uint32_t watchdogResetRun = 0U;

    /// WHY THE PART RESTARTED, as a whole fault code — `boot_reason_power_on`,
    /// `boot_reason_task_wdt`, `boot_reason_brownout` and the rest.
    ///
    /// A PORT, AND THE WHOLE STRING RATHER THAN AN ENUM, for the same reason
    /// `bootId` and `watchdogResetRun` are ports: `esp_reset_reason()` is an
    /// IDF call, no `lib/` but `esp32_hal/` may include one, and a loop that
    /// reached for it could only ever be tested against itself. Handing over
    /// the assembled code rather than a number keeps the mapping in the one
    /// file that already knows the enumerators, and keeps the closed
    /// vocabulary in `FaultLog.h` from needing an IDF header to express it.
    ///
    /// `nullptr` means "this board does not know", which records nothing —
    /// which is what a host test and a simulator honestly are.
    const char* bootReason = nullptr;

    /// The heartbeat response buffer. Owned by the composition root and static
    /// there, because the contract allows 4096 bytes and a 4.6 KB local under a
    /// blocking HTTP call is a crash that reads as a random reset.
    char* heartbeatBody = nullptr;
    size_t heartbeatBodyCap = 0U;
  };

  explicit GateApp(const Ports& ports);

  /// The very first thing that happens on this board, before the watchdog,
  /// before the UART and before the radio.
  ///
  /// Both output pins get their level written into the output register BEFORE
  /// the pin drives anything — the lock LOCKED, the lamp dark. A GPIO leaves
  /// reset as an input and `pinMode(OUTPUT)` starts driving whatever is already
  /// latched, so on a board wired the other way round the obvious ordering is a
  /// door that clicks open on every boot, including the ones a watchdog reset
  /// causes at three in the morning.
  ///
  /// Separate from begin() because the ordering genuinely is: this, then the
  /// hardware the composition root owns, then the rest.
  void beginOutputs();

  /// The logical boot, after the peripherals are open and the MAC is known.
  /// Seeds the uptime, empties the assembler, arms the first heartbeat, opens
  /// the event queue and puts a `boot` event in it.
  void begin();

  /// One pass of the loop.
  void pass();

  /// Whether the task watchdog actually took.
  ///
  /// `Esp32Watchdog::begin` is a RECONFIGURATION over the core's own five-second
  /// TWDT and it can refuse. False means the board is running under a watchdog
  /// it did not choose, which makes `GateConfig.h`'s watchdog assert a statement
  /// about an intention rather than about the real timeout — so the lamp shows
  /// the fault pattern for as long as it is false.
  ///
  /// THE DOOR IS UNAFFECTED, deliberately. A board that refused to open for a
  /// missing watchdog would be a door that admits nobody, which is far worse
  /// than one running on five seconds instead of fifteen. Nothing on this path
  /// touches the lock in either direction.
  void setWatchdogArmed(bool armed);

  // --- observation, for the host suite and for nothing else ----------------

  /// Blocking calls made in the pass that just ran. Never more than one.
  uint16_t blockingCallsLastPass() const { return blockingCalls_; }

  /// The release time the last accepted heartbeat established.
  uint32_t unlockMs() const { return unlockMs_; }

  uint32_t heartbeatIntervalMs() const { return heartbeatMs_; }

  bool linkUp() const { return linkUp_; }

  /// What the last heartbeat did to the roster. `replaced` false after a
  /// heartbeat that carried no roster, or whose body was cut short.
  const devlink::SyncResult& lastSync() const { return lastSync_; }

  /// Heartbeats, since boot, that the server answered and from which no roster
  /// could be adopted — a body cut short, malformed chunk framing, a body that
  /// did not fit, or one missing the key the contract says is always present.
  /// Sent in the next heartbeat REQUEST as `no_push` when it is not zero,
  /// because there is nowhere else on this board a technician could see it.
  /// Saturates rather than wrapping. See GateHeartbeat.h.
  uint32_t noPushHeartbeats() const { return noPushHeartbeats_; }

  /// Release windows the hard cap ended, since boot. See the member.
  uint32_t capForcedCloses() const { return capForcedCloses_; }

  /// Milliseconds the first network call of this boot was held back for, after
  /// a watchdog reset. Zero on a healthy boot. See BootRecovery.h.
  uint32_t firstCallHeldBackMs() const { return firstCallHeldBackMs_; }

  /// This boot's identity, as every uploaded batch carries it. Observable so a
  /// test and the simulator's console can say WHICH boot a record belongs to.
  uint32_t bootId() const { return bootId_; }

  /// The two since-boot counters exactly as the next request will carry them.
  GateDiagnostics diagnostics() const {
    // `codes:m1` on every heartbeat: this image verifies the single rotating
    // member code offline, and the server keys what it sends and the club's
    // automatic cut-over on the latest heartbeat it saw.
    return GateDiagnostics{noPushHeartbeats_, saturate(queue_.overflowed()), true};
  }

  /// The member-code sync as the last heartbeat left it — for the host suite
  /// and the simulator's console.
  const memcode::StepClock& stepClock() const { return stepClock_; }

  uint8_t codeKeys() const { return codeKeys_.size(); }

  /// The fault aggregator, for the host suite and the simulator's console.
  /// Non-const because a console prints a drain in the simulator's own loop.
  FaultLog& faults() { return faults_; }

private:
  void pumpScanner();
  void feedByte(uint8_t byte);
  void refuseUnreadableLine();
  void decideScan(const char* token);

  /// The roster's answer — or, for a v1 member code, the offline verifier's
  /// and then the roster's by REF. `member` is filled for a v1 code.
  ScanDecision decideFromRoster(const char* token, uint32_t nowMs, memcode::Verdict& member);

  /// Records a v1 code as used once the lock was actually given time: the
  /// offline verdict's step, or — for an open the SERVER decided — whatever
  /// this board can establish (memcode::recordOnlineUse).
  void recordCodeUse(const ScanDecision& decision, const memcode::Verdict& member, const char* token,
                     uint32_t grantedMs, uint32_t nowMs);
  void pumpLock();
  void pumpLink();
  void pumpEvents();

  /// THE FAULT PASS. Reads the two faults that are only observable as a CHANGE
  /// — the ring's since-boot loss total and the breaker's closed→open edge —
  /// and then drains AT MOST ONE fault event into the queue.
  ///
  /// One per pass for the reason the event drain is one per pass: eight due
  /// codes pushed in one iteration is eight of a 64-slot ring spent on
  /// diagnostics in a single millisecond, which is the eviction the whole of
  /// `FaultLog` exists to prevent, arriving from the other direction.
  ///
  /// It makes NO blocking call, so it is outside the one-call-per-pass rule and
  /// runs on every pass including the ones an upload took.
  void pumpFaults();

  /// One occurrence of `code`, stamped from a fresh clock read like every other
  /// instant on this side of a blocking call.
  void fault(const char* code);

  void applyEventReaction(uint16_t status, const char* response);

  /// Applies whatever the heartbeat's `gate` object carried — the release time,
  /// whether the board's own clamp had to change it, and the two fault
  /// settings. Separate from `adoptHeartbeat` so that one keeps a shape a
  /// reader can hold, and so the complexity gate stays satisfied.
  void adoptGateSettings(const char* body, size_t len);

  /// Arms or clears the drain's backoff, from whether the post that just
  /// finished actually MOVED the queue. Not from its status: a 200 that
  /// acknowledges nothing leaves the head exactly where a 429 does.
  void armEventRetry(bool queueMoved);

  /// Whether the heartbeat would take the pass's one blocking call if it got
  /// it — the cadence, the radio AND the spacing floor. Leaving the floor out
  /// is a bound that defers a member's scan to a heartbeat that cannot run.
  bool heartbeatReady(uint32_t nowMs) const;

  /// Whether the event drain would take the pass's one blocking call if it got
  /// it. Asked in `pass()` so a busy scanner is bounded against BOTH uploads,
  /// and asked again inside `pumpEvents` because the pass moves on between the
  /// two and a fresh clock is the rule everywhere here.
  bool eventDrainReady(uint32_t nowMs) const;

  void pumpHeartbeat();
  void adoptHeartbeat(const HttpOutcome& outcome);

  /// The club took this board out of service. A roster committed EMPTY rather
  /// than abandoned, so `everLoaded()` stays true and the refusal is
  /// `not_recognised` rather than `roster_stale`.
  void commitEmptyRoster();

  void pumpLed();

  /// Whether to ask the API, on the same judgement everywhere: the radio AND
  /// the breaker.
  Attempt attempt(uint32_t nowMs);

  /// Applies a decision to the door and the lamp, and answers with what the
  /// lock was ACTUALLY given after both bounds — which is what the queued event
  /// has to carry, not what was asked for.
  /// Non-const: a decision that asked for the door can come back REFUSED, when
  /// the lock turns out to still be relatching — see `markRelocking` and round
  /// G4's A1. The caller records what actually happened, not what was decided.
  uint32_t apply(ScanDecision& decision, uint32_t nowMs);

  void queue(const ScanDecision& decision, const char* subject, uint32_t nowMs, uint32_t grantedMs);

  /// Offers a decision to the log, if there is one. Called LAST on every
  /// decision path, after the door, the lamp and the queue — an observer that
  /// ran earlier would be an observer a reader could mistake for a step.
  void report(const ScanDecision& decision, const char* token, uint32_t nowMs, uint32_t grantedMs);

  /// Kicked immediately before and immediately after every blocking call, and
  /// the deadline re-checked with a fresh clock on the way out.
  void beforeBlocking();
  void afterBlocking();

  hal::IClock& clock_;
  IScannerBytes& scanner_;
  IWatchdog& watchdog_;
  ILink& link_;
  GateApi& api_;
  devlink::ApiBreaker& breaker_;
  LockDriver& lock_;
  UnlockTimer& unlock_;
  LedPattern& led_;
  IPinOut& ledPin_;
  ScanAssembler& assembler_;
  ScanDebounce& debounce_;
  GateRoster& roster_;
  GateQueue& queue_;
  FaultLog& faults_;

  /// A POINTER, unlike every other port here, because it is the only one that
  /// is genuinely absent on the hardware.
  IDecisionLog* log_;

  const char* mac_;
  const char* firmwareVersion_;
  /// This boot's identity, from the composition root. See Ports::bootId.
  uint32_t bootId_;
  /// Consecutive watchdog resets before this boot. See Ports::watchdogResetRun.
  uint32_t watchdogResetRun_;
  /// Why the part restarted, as a whole fault code. See Ports::bootReason.
  const char* bootReason_;
  char* heartbeatBody_;
  size_t heartbeatBodyCap_;
  bool ledActiveHigh_;

  tb::Uptime64 uptime_;
  tb::Deadline heartbeatAt_;

  /// THE FIRST NETWORK CALL OF THIS BOOT, held back after a watchdog reset
  /// (round G4, A4). Disarmed on a healthy boot, which is every boot on a
  /// healthy board, so this costs nothing in normal service.
  ///
  /// It gates the HEARTBEAT specifically, because the heartbeat is the first
  /// thing a board does with its radio — `pumpLink`'s up edge arms it to "now"
  /// — and is therefore the call a dribbling peer holds until the watchdog
  /// fires. The event drain is gated with it: a board with a boot event in its
  /// ring would otherwise reach the same peer on the same first pass.
  tb::Deadline firstCallAt_;

  /// When this board may next ASK THE SERVER about a scan, whatever token is
  /// presented. See `kMinScanCallSpacingMs` and round G4's A2: the debounce
  /// bounds repeats, and two alternating tokens defeated it entirely.
  ///
  /// Armed from the instant of the ATTEMPT, like the heartbeat's own floor, so
  /// a slow call does not make the next member wait for the call's duration on
  /// top of the spacing.
  tb::Deadline scanCallFloorAt_;

  /// When an unreadable line may next produce an answer. See
  /// `kUnreadableFeedbackMs`: the feedback L1 added is rate-limited so that a
  /// noisy cable cannot strobe the lamp or fill the event ring.
  tb::Deadline unreadableAt_;

  /// THE FLOOR, armed after every heartbeat ATTEMPT. Whatever re-armed
  /// `heartbeatAt_` — the cadence, or a link-up edge — no attempt happens
  /// within `kMinHeartbeatSpacingMs` of the last one. A flapping radio re-arms
  /// the heartbeat to "now" on every up edge, which without this was one call
  /// per pass: 179 999 heartbeats in a simulated hour against a cadence of 120.
  tb::Deadline heartbeatFloorAt_;

  uint32_t heartbeatMs_ = kGateConfig.heartbeatMs;

  /// When the event drain may next try, and how long it is currently waiting.
  /// Disarmed — the state a healthy board is always in — means "now".
  tb::Deadline eventsAt_;
  uint32_t eventBackoffMs_ = 0U;

  /// Consecutive passes in which a SCAN took the pass's one blocking call while
  /// an UPLOAD — a due heartbeat, or a ready event drain — was waiting for it.
  /// At kMaxScanPassesBeforeUpload the upload goes first, so a scanner that
  /// never stops talking cannot hold the call budget for ever.
  ///
  /// RESET ON A LINK DROP as well as by an upload that got its call. A board
  /// whose radio went away carries no debt from before the outage: the four
  /// passes it had spent deferring were spent against a heartbeat that could
  /// not have run anyway, and carrying them forward makes the first pass after
  /// the link returns take the call from a member standing at the door.
  uint8_t scanDeferrals_ = 0U;

  /// Heartbeats the server answered that pushed no roster. A diagnostic with no
  /// effect on any decision this class makes; saturating, never wrapping.
  uint32_t noPushHeartbeats_ = 0U;

  /// What `firstCallAt_` was armed for at boot, kept so the console and the
  /// host suite can say the backoff happened rather than infer it from silence.
  uint32_t firstCallHeldBackMs_ = 0U;

  /// Release windows the HARD CAP ended, since boot (round G4, A1).
  ///
  /// A rising count is somebody holding a door open — a phone taped to the
  /// reader, a scanner jammed against a frame, or two codes being alternated —
  /// and it is the only number on this board that says so. Saturating.
  ///
  /// NOT ON THE WIRE, and said plainly rather than implied: there is no event
  /// kind for it and no heartbeat field, both of which are wire changes with
  /// corpus vectors and a backend behind them. It reaches the native
  /// simulator's `status` line and the host suite, and the `relocking` refusals
  /// the dwell produces afterwards DO reach the queue when the board is
  /// offline. Putting it on the wire is owed.
  uint32_t capForcedCloses_ = 0U;

  /// What the last heartbeat said a release should last. The build-flag default
  /// until the first accepted one, which is what makes a board that has never
  /// spoken to the API still able to open a door for a rostered member.
  uint32_t unlockMs_ = kGateConfig.unlockDefaultMs;

  /// The ring's since-boot loss total as this class last saw it.
  ///
  /// `EventQueue::overflowed()` is a TOTAL and the fault channel wants
  /// OCCURRENCES, so what is recorded is the jump between two passes. A board
  /// back from an evening offline can jump by hundreds in one pass, which is
  /// why `FaultLog::recordMany` exists rather than a loop.
  uint32_t eventsLostSeen_ = 0U;

  /// The breaker's state as this class last saw it, so the closed→OPEN edge is
  /// one fault rather than one per pass for as long as it stays open.
  bool breakerWasOpen_ = false;

  bool linkUp_ = false;
  bool blocked_ = false;
  uint16_t blockingCalls_ = 0U;
  devlink::SyncResult lastSync_;

  /// THE SINGLE ROTATING MEMBER CODE, offline (docs/specs/member-code.md §6):
  /// the step clock counted from the last heartbeat's `code_step`, the per-day
  /// keys a v1 code's OFF half is checked with, and the uses this door has
  /// acted on. Owned here rather than injected: nothing about them is a
  /// platform fact, and all three are RAM that the next heartbeat refills.
  /// Emptied with the roster when the club takes this board out of service.
  memcode::StepClock stepClock_{kGateConfig.rosterMaxAgeMs};
  memcode::KeyRing<kGateKeyRingSlots> codeKeys_;
  memcode::ReplayRing<kGateReplaySlots> codeUses_;
  /// Wrong OFF codes presented here lately. A REF is public, so a door in its
  /// offline fallback is a door that could be guessed open. GuessGuard.h.
  memcode::GuessGuard codeGuard_;
};

} // namespace gatelogic

#endif // CRUSADERS_GATELOGIC_GATEAPP_H
